import { useTheme } from '@mui/styles';
import adobeImg from '../../../../assets/images/landing/adobe-express.png';
import canvaImg from '../../../../assets/images/landing/canva.png';

import { Box, Typography, IconButton, Tooltip } from '@mui/material';

import { Link as LinkIcon, DesktopWindows, ImageSearch, AutoAwesome } from '@mui/icons-material';

const MediaSourceIcons = ({ activeTab, setOpenGallery, setOpenDeepSeek }) => {
    const theme = useTheme();
    const sources = [
        {
            icon: <DesktopWindows style={{ color: 'gray', fontSize: 22 }} />,
            action: () => document.getElementById('file-upload').click(),
            label: 'Computer',
            disabled: activeTab !== 'media'
        },
        {
            icon: <i className="fab fa-google-drive fs-18" style={{ color: 'gray' }} />,
            label: 'Google Drive',
            disabled: activeTab !== 'media'
        },
        {
            icon: <img src={adobeImg} alt="Adobe" style={{ width: 24, height: 24 }} />,
            label: 'Adobe Express',
            disabled: activeTab !== 'media'
        },
        {
            icon: <img src={canvaImg} alt="Canva" style={{ width: 24, height: 24 }} />,
            label: 'Canva',
            disabled: activeTab !== 'media'
        },
        {
            icon: <AutoAwesome style={{ color: 'gray', fontSize: 22 }} />,
            label: 'AI Image',
            action: () => setOpenDeepSeek(true),
            disabled: activeTab !== 'media'
        },
        {
            icon: <ImageSearch style={{ color: 'gray', fontSize: 22 }} />,
            label: 'Search Online',
            action: () => setOpenGallery(true),
            disabled: activeTab !== 'media'
        }
    ];

    return (
        <Box
            sx={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'center',
                gap: 0,
                p: 3,
                borderBottom: `1px solid ${theme.palette.primary.main}`
            }}
        >
            {sources.map((item, index) => (
                <Tooltip key={index} title={item.disabled ? 'Switch to Media tab to select images' : item.label}>
                    <span>
                        <IconButton
                            title={item.label}
                            onClick={item.action}
                            disabled={item.disabled}
                            sx={{
                                '&:hover': { backgroundColor: !item.disabled ? '#f5f5f5' : 'none' },
                                p: 0.1,
                                minWidth: 'auto',
                                color: theme.palette.text.primary,
                                opacity: item.disabled ? 0.5 : 1,
                                cursor: item.disabled ? 'not-allowed' : 'pointer'
                            }}
                        >
                            {item.icon}
                            <Typography
                                variant="caption"
                                sx={{
                                    ml: 0.5,
                                    color: theme.palette.text.dark,
                                    opacity: item.disabled ? 0.5 : 1
                                }}
                            >
                                {item.label}
                            </Typography>
                        </IconButton>
                    </span>
                </Tooltip>
            ))}
        </Box>
    );
};

export default MediaSourceIcons;
