/* eslint-disable no-restricted-syntax */
import { useState, useRef, useEffect } from 'react';
import PostCreationPanel from './PostCreation';
import PostPreviewPanel from './PostPreviewPanel';
import useAuth from 'hooks/useAuth';
import { Box, Grid } from '@mui/material';
import { Facebook, Instagram, Twitter, YouTube, LinkedIn, MusicNote as TikTokIcon, Pinterest } from '@mui/icons-material';

// Social media platforms
const socialPlatforms = [
    { id: 'facebook', name: 'Facebook', icon: <Facebook />, color: 'primary' },
    { id: 'instagram', name: 'Instagram', icon: <Instagram color="error" />, color: 'error' },
    { id: 'twitter', name: 'Twitter', icon: <Twitter />, color: 'info' },
    { id: 'youtube', name: 'YouTube', icon: <YouTube color="error" />, color: 'error' },
    { id: 'linkedin', name: 'LinkedIn', icon: <LinkedIn color="info" />, color: 'info' },
    { id: 'tiktok', name: 'TikTok', icon: <TikTokIcon color="secondary" />, color: 'secondary' },
    { id: 'pinterest', name: 'Pinterest', icon: <Pinterest color="error" />, color: 'error' }
];

const Composer = () => {
    const { user } = useAuth();
    const [activeTab, setActiveTab] = useState('media');
    const [selectedProfile, setSelectedProfile] = useState('');
    const [caption, setCaption] = useState('');

    // NEW: Unified media state
    const [mediaItems, setMediaItems] = useState([]);
    const [currentPreviewIndex, setCurrentPreviewIndex] = useState(0);

    const [isDragging, setIsDragging] = useState(false);
    const [linkUrl, setLinkUrl] = useState('');
    const previewRefs = useRef({});
    const iconsContainerRef = useRef(null);
    const [activePlatform, setActivePlatform] = useState('facebook');

    // Handle icon click - scroll to corresponding content
    const handleIconClick = (platformId, event) => {
        event.stopPropagation();
        event.preventDefault();

        setActivePlatform(platformId);
        previewRefs.current[platformId]?.scrollIntoView({
            behavior: 'smooth',
            block: 'start'
        });
    };

    // Handle scroll to update active platform
    const handlePreviewScroll = () => {
        const previewContainer = previewRefs.current.container;
        if (!previewContainer) return null;

        const containerTop = previewContainer.getBoundingClientRect().top;
        for (const platform of socialPlatforms) {
            const element = previewRefs.current[platform.id];
            if (element) {
                const elementTop = element.getBoundingClientRect().top - containerTop;
                const elementHeight = element.clientHeight;

                if (elementTop <= 100 && elementTop + elementHeight > 100) {
                    setActivePlatform(platform.id);
                    const iconElement = previewRefs.current[`icon-${platform.id}`];
                    if (iconElement && iconsContainerRef.current) {
                        const container = iconsContainerRef.current;
                        const iconLeft = iconElement.offsetLeft;
                        const iconWidth = iconElement.clientWidth;
                        const containerWidth = container.clientWidth;

                        container.scrollTo({
                            left: iconLeft - containerWidth / 2 + iconWidth / 2,
                            behavior: 'smooth'
                        });
                    }
                    break;
                }
            }
        }
        return null;
    };

    // Set up scroll listener
    useEffect(() => {
        const previewContainer = previewRefs.current.container;
        if (previewContainer) {
            previewContainer.addEventListener('scroll', handlePreviewScroll);
            return () => {
                previewContainer.removeEventListener('scroll', handlePreviewScroll);
            };
        }
        return undefined;
    }, []);

    // Handle drag and drop events
    const handleDragEnter = (e) => {
        e.preventDefault();
        setIsDragging(true);
    };

    const handleDragLeave = (e) => {
        e.preventDefault();
        setIsDragging(false);
    };

    const handleDragOver = (e) => {
        e.preventDefault();
    };

    const handleDrop = (e) => {
        e.preventDefault();
        setIsDragging(false);
        const files = Array.from(e.dataTransfer.files);

        // NEW: Handle multiple files
        const newMediaItems = files
            .filter((file) => file.type.startsWith('image/') || file.type.startsWith('video/'))
            .map((file) => ({
                id: `file-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                file,
                url: URL.createObjectURL(file),
                type: file.type.startsWith('video/') ? 'video' : 'image',
                source: 'computer'
            }));

        if (newMediaItems.length > 0) {
            setMediaItems((prev) => [...prev, ...newMediaItems]);

            // Set the first new item as preview if no current preview
            if (mediaItems.length === 0) {
                setCurrentPreviewIndex(0);
            }
        }
    };

    // Handle media selection from external sources
    const handleMediaSelect = (items) => {
        const newItems = items.map((item) => ({
            ...item,
            id: item.id || `item-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            type: 'image', // Assuming external sources are always images
            source: item.source || 'unsplash'
        }));

        setMediaItems((prev) => [...prev, ...newItems]);

        // Set the first new item as preview if no current preview
        if (mediaItems.length === 0) {
            setCurrentPreviewIndex(0);
        }
    };

    return (
        <Grid
            container
            spacing={2}
            sx={{
                margin: '20px auto 20px',
                px: 2
            }}
        >
            {/* Left Section - Select Source and New Post */}
            <Grid item xs={12} md={7} lg={8}>
                <PostCreationPanel
                    activeTab={activeTab}
                    setActiveTab={setActiveTab}
                    selectedProfile={selectedProfile}
                    setSelectedProfile={setSelectedProfile}
                    caption={caption}
                    setCaption={setCaption}
                    isDragging={isDragging}
                    setIsDragging={setIsDragging}
                    linkUrl={linkUrl}
                    setLinkUrl={setLinkUrl}
                    handleMediaSelect={handleMediaSelect}
                    handleDragEnter={handleDragEnter}
                    handleDragLeave={handleDragLeave}
                    handleDragOver={handleDragOver}
                    handleDrop={handleDrop}
                    // NEW: Pass media items and preview index
                    mediaItems={mediaItems}
                    setMediaItems={setMediaItems}
                    currentPreviewIndex={currentPreviewIndex}
                    setCurrentPreviewIndex={setCurrentPreviewIndex}
                />
            </Grid>

            {/* Right Section - Post Preview */}
            <Grid
                item
                xs={12}
                md={5}
                lg={4}
                sx={{
                    position: { md: 'sticky' },
                    top: 20,
                    alignSelf: 'flex-start'
                }}
            >
                <PostPreviewPanel
                    caption={caption}
                    mediaItems={mediaItems}
                    currentPreviewIndex={currentPreviewIndex}
                    previewRefs={previewRefs}
                    iconsContainerRef={iconsContainerRef}
                    activePlatform={activePlatform}
                    handleIconClick={handleIconClick}
                />
            </Grid>
        </Grid>
    );
};

export default Composer;
