import PropTypes from 'prop-types';
import { Box, Typography, Button, IconButton, Paper } from '@mui/material';
import { Send, Facebook, Instagram, Twitter, YouTube, LinkedIn, MusicNote as TikTokIcon, Pinterest } from '@mui/icons-material';
import SocialPreview from './SocialPreview';

const socialPlatforms = [
    { id: 'facebook', name: 'Facebook', icon: <Facebook />, color: 'primary' },
    { id: 'instagram', name: 'Instagram', icon: <Instagram color="error" />, color: 'error' },
    { id: 'twitter', name: 'Twitter', icon: <Twitter />, color: 'info' },
    { id: 'youtube', name: 'YouTube', icon: <YouTube color="error" />, color: 'error' },
    { id: 'linkedin', name: 'LinkedIn', icon: <LinkedIn color="info" />, color: 'info' },
    { id: 'tiktok', name: 'TikTok', icon: <TikTokIcon color="secondary" />, color: 'secondary' },
    { id: 'pinterest', name: 'Pinterest', icon: <Pinterest color="error" />, color: 'error' }
];

const PostPreviewPanel = ({
    caption,
    mediaItems = [],
    currentPreviewIndex,
    previewRefs,
    iconsContainerRef,
    activePlatform,
    handleIconClick
}) => {
    const setPreviewRef = (el, key) => {
        previewRefs.current[key] = el;
    };

    const setIconRef = (el, platformId) => {
        previewRefs.current[`icon-${platformId}`] = el;
    };

    // Get the current preview media item
    const previewMedia = mediaItems.length > 0 && currentPreviewIndex < mediaItems.length ? mediaItems[currentPreviewIndex] : null;

    return (
        <>
            <Typography variant="h6" sx={{ mb: 1 }}>
                3 - Post Preview
            </Typography>

            <Paper
                elevation={3}
                sx={{
                    border: '1px solid #0a6c7d',
                    borderRadius: 2,
                    overflow: 'hidden',
                    background: 'white'
                }}
            >
                {/* Preview Tabs */}
                <Box
                    ref={iconsContainerRef}
                    sx={{
                        display: 'flex',
                        justifyContent: 'space-around',
                        borderBottom: '1px solid',
                        borderColor: 'divider',
                        px: 1,
                        overflowX: 'auto',
                        '&::-webkit-scrollbar': {
                            height: '4px'
                        },
                        '&::-webkit-scrollbar-thumb': {
                            backgroundColor: 'rgba(0,0,0,0.2)',
                            borderRadius: '2px'
                        }
                    }}
                >
                    {socialPlatforms.map((platform) => (
                        <Box
                            key={platform.id}
                            ref={(el) => setIconRef(el, platform.id)}
                            sx={{
                                display: 'flex',
                                flexDirection: 'column',
                                alignItems: 'center',
                                cursor: 'pointer',
                                py: 1,
                                position: 'relative'
                            }}
                            onClick={(e) => {
                                e.preventDefault();
                                handleIconClick(platform.id, e);
                            }}
                        >
                            <IconButton size="large" color={activePlatform === platform.id ? platform.color : 'default'}>
                                {platform.icon}
                            </IconButton>
                            {activePlatform === platform.id && (
                                <Box
                                    sx={{
                                        position: 'absolute',
                                        bottom: 0,
                                        width: '100%',
                                        height: 2,
                                        backgroundColor: (theme) => theme.palette[platform.color].main
                                    }}
                                />
                            )}
                        </Box>
                    ))}
                </Box>

                {/* Preview Content - Feed View */}
                <Box
                    ref={(el) => setPreviewRef(el, 'container')}
                    sx={{
                        p: 2,
                        height: 500,
                        overflowY: 'auto',
                        background: 'white',
                        '&::-webkit-scrollbar': {
                            width: '0.4em'
                        },
                        '&::-webkit-scrollbar-track': {
                            boxShadow: 'inset 0 0 6px rgba(0,0,0,0.00)',
                            webkitBoxShadow: 'inset 0 0 6px rgba(0,0,0,0.00)'
                        },
                        '&::-webkit-scrollbar-thumb': {
                            backgroundColor: 'rgba(0,0,0,.1)',
                            outline: '1px solid slategrey'
                        }
                    }}
                >
                    {socialPlatforms.map((platform) => (
                        <Box key={platform.id} ref={(el) => setPreviewRef(el, platform.id)} sx={{ scrollMarginTop: '16px' }}>
                            {/* Updated: Pass previewMedia instead of selectedMedia */}
                            <SocialPreview platform={platform.id} caption={caption} mediaItem={previewMedia} />
                        </Box>
                    ))}
                </Box>
            </Paper>

            {/* Send Now Button */}
            <Box sx={{ display: 'flex', justifyContent: 'center', mt: 2 }}>
                <Button variant="contained" startIcon={<Send />} sx={{ textTransform: 'none' }}>
                    Send now
                </Button>
            </Box>
        </>
    );
};

PostPreviewPanel.propTypes = {
    caption: PropTypes.string.isRequired,
    mediaItems: PropTypes.array,
    currentPreviewIndex: PropTypes.number,
    previewRefs: PropTypes.shape({
        current: PropTypes.object
    }).isRequired,
    iconsContainerRef: PropTypes.oneOfType([PropTypes.func, PropTypes.shape({ current: PropTypes.instanceOf(Element) })]),
    activePlatform: PropTypes.string.isRequired,
    handleIconClick: PropTypes.func.isRequired
};

// Default props for safety
PostPreviewPanel.defaultProps = {
    mediaItems: [],
    currentPreviewIndex: 0
};

export default PostPreviewPanel;
