import React, { useState, useEffect, useCallback } from 'react';
import SearchIcon from '@mui/icons-material/Search';
import { ArrowDropDown, Close as CloseIcon, Check as CheckIcon } from '@mui/icons-material';
import { useTheme } from '@mui/material/styles';
import {
    Button,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Grid,
    Typography,
    CircularProgress,
    IconButton,
    Box,
    Avatar,
    Chip,
    Stack,
    TextField,
    InputAdornment,
    MenuItem,
    Select
} from '@mui/material';
import ApiRequest from 'utils/apiService';

export default function UnsplashGalleryDialog({ open, onClose, onSelect, selectedImages = [], onFinalSubmit, singleSelect = false }) {
    const theme = useTheme();
    const [images, setImages] = useState([]);
    const [page, setPage] = useState(1);
    const [loading, setLoading] = useState(false);
    const [hasMore, setHasMore] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');
    const [searchSource, setSearchSource] = useState('unsplash');
    const [isSearching, setIsSearching] = useState(false);
    const [selected, setSelected] = useState([]);
    const PER_PAGE = 10;

    const fetchImages = useCallback(
        async (reset = false) => {
            if (loading) return;

            setLoading(true);
            const currentPage = reset ? 1 : page;

            try {
                const params = {
                    page: currentPage,
                    perPage: PER_PAGE,
                    query: 'home'
                };

                if (searchQuery.trim()) {
                    params.query = searchQuery;
                }

                const response = await ApiRequest('GET', 'unsplash/search?', {}, params);
                const newImages = response?.data || [];

                setImages((prev) => (reset ? newImages : [...prev, ...newImages]));
                setPage(currentPage + 1);
                setHasMore(newImages.length === PER_PAGE);
            } catch (error) {
                console.error('Error fetching images:', error);
            } finally {
                setLoading(false);
            }
        },
        [page, searchQuery, loading]
    );

    const fetchImagesRef = React.useRef();
    useEffect(() => {
        fetchImagesRef.current = fetchImages;
    }, [fetchImages]);

    // Initialize selection when dialog opens
    useEffect(() => {
        if (open) {
            setSelected(selectedImages);
            fetchImages(true); // Fetch initial images
        }
    }, [open]);

    // Reset state when dialog closes
    useEffect(() => {
        if (!open) {
            setSelected([]);
            setSearchQuery('');
            setImages([]);
            setPage(1);
            setHasMore(true);
        }
    }, [open]);

    // Handle search with debounce
    useEffect(() => {
        if (!open) return undefined;

        const timer = setTimeout(() => {
            if (searchQuery.trim()) {
                fetchImagesRef.current?.(true);
            }
        }, 500);

        // Return cleanup function explicitly
        return () => clearTimeout(timer);
    }, [searchQuery, searchSource, open]);

    const handleScroll = useCallback(
        (e) => {
            const { scrollTop, clientHeight, scrollHeight } = e.currentTarget;
            if (scrollHeight - (scrollTop + clientHeight) < 100 && !loading && hasMore) {
                fetchImages();
            }
        },
        [fetchImages, loading, hasMore]
    );

    const isSelected = (image) => selected.some((img) => img.id === image.id);

    const handleImageClick = (image) => {
        if (singleSelect) {
            const newSelection = isSelected(image) ? [] : [image];
            setSelected(newSelection);
            return;
        }

        if (isSelected(image)) {
            setSelected((prev) => prev.filter((img) => img.id !== image.id));
        } else if (selected.length < 6) {
            setSelected((prev) => [...prev, image]);
        }
    };

    const handleChipDelete = (image) => {
        setSelected((prev) => prev.filter((img) => img.id !== image.id));
    };

    const handleFinalSubmit = () => {
        onSelect(selected);
        onFinalSubmit();
        onClose();
    };

    return (
        <Dialog
            open={open}
            onClose={onClose}
            maxWidth="lg"
            fullWidth
            scroll="paper"
            PaperProps={{ sx: { backgroundColor: 'white' } }}
            aria-labelledby="unsplash-gallery-title"
        >
            <DialogTitle id="unsplash-gallery-title" style={{ background: theme.palette.text.primary }}>
                <Box display="flex" justifyContent="space-between" alignItems="center">
                    <Typography variant="h2">Search Media Online</Typography>
                    <IconButton onClick={onClose}>
                        <CloseIcon />
                    </IconButton>
                </Box>
                <Box sx={{ mt: 2, display: 'flex', justifyContent: 'center' }}>
                    <TextField
                        variant="outlined"
                        placeholder="Search for images..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        sx={{
                            width: '70%',
                            '& .MuiOutlinedInput-root': {
                                backgroundColor: theme.palette.text.primary,
                                '& fieldset': {
                                    border: `2px solid ${theme.palette.primary.main}`,
                                    borderRadius: '28px'
                                },
                                '&:hover fieldset': {
                                    border: `2px solid ${theme.palette.primary.main}`
                                }
                            }
                        }}
                        InputProps={{
                            startAdornment: (
                                <InputAdornment position="start">
                                    <SearchIcon />
                                </InputAdornment>
                            ),
                            endAdornment: (
                                <InputAdornment position="end">
                                    <Stack direction="row" spacing={0} alignItems="center">
                                        <Select
                                            value={searchSource}
                                            onChange={(e) => setSearchSource(e.target.value)}
                                            sx={{
                                                '& .MuiSelect-select': {
                                                    backgroundColor: theme.palette.text.primary,
                                                    color: 'black',
                                                    borderRadius: '0 !important',
                                                    padding: '8px 32px 8px 16px'
                                                },
                                                '& .MuiOutlinedInput-notchedOutline': {
                                                    borderLeft: '0.4px solid gray !important',
                                                    borderRadius: '0 !important',
                                                    borderRight: '0 !important'
                                                },
                                                '& .MuiSvgIcon-root': { color: 'black', right: '8px' },
                                                borderRadius: '0 !important'
                                            }}
                                            IconComponent={ArrowDropDown}
                                        >
                                            <MenuItem value="unsplash">Unsplash</MenuItem>
                                        </Select>
                                    </Stack>
                                </InputAdornment>
                            )
                        }}
                    />
                </Box>
            </DialogTitle>

            <DialogContent
                dividers
                onScroll={handleScroll}
                sx={{
                    height: '60vh',
                    background: theme.palette.text.primary,
                    overflowX: 'hidden'
                }}
            >
                <Grid container spacing={2}>
                    {images?.map((image) => (
                        <Grid item xs={12} sm={6} md={3} key={image.id}>
                            <Box
                                position="relative"
                                onClick={() => handleImageClick(image)}
                                sx={{
                                    cursor: 'pointer',
                                    border: isSelected(image) ? `3px solid ${theme.palette.primary.main}` : '3px solid transparent',
                                    borderRadius: 1,
                                    overflow: 'hidden',
                                    aspectRatio: '1/1',
                                    '&:hover': {
                                        opacity: 0.9
                                    }
                                }}
                            >
                                <img
                                    src={image?.urls?.small}
                                    alt={image?.alt || 'Unsplash image'}
                                    style={{
                                        width: '100%',
                                        height: '100%',
                                        objectFit: 'cover',
                                        display: 'block'
                                    }}
                                />
                                {isSelected(image) && (
                                    <Box
                                        sx={{
                                            position: 'absolute',
                                            top: 8,
                                            right: 8,
                                            backgroundColor: theme.palette.primary.main,
                                            borderRadius: '50%',
                                            width: 24,
                                            height: 24,
                                            display: 'flex',
                                            alignItems: 'center',
                                            justifyContent: 'center'
                                        }}
                                    >
                                        <CheckIcon sx={{ color: 'white', fontSize: 16 }} />
                                    </Box>
                                )}
                            </Box>
                            <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
                                {image.alt?.substring(0, 20) || 'Untitled'}
                            </Typography>
                        </Grid>
                    ))}
                </Grid>

                {loading && (
                    <Box display="flex" justifyContent="center" my={4}>
                        <CircularProgress />
                    </Box>
                )}

                {!loading && images.length === 0 && (
                    <Box display="flex" justifyContent="center" alignItems="center" height="200px">
                        <Typography variant="h6" color="textSecondary">
                            No images found
                        </Typography>
                    </Box>
                )}

                {!hasMore && images.length > 0 && (
                    <Typography align="center" color="textSecondary" my={2}>
                        No more images to load
                    </Typography>
                )}
            </DialogContent>

            <DialogActions sx={{ background: theme.palette.text.primary, p: 2 }}>
                <Stack direction="row" spacing={2} sx={{ width: '100%', justifyContent: 'space-between' }}>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap', maxWidth: '60%' }}>
                        {selected.map((image) => (
                            <Chip
                                key={image.id}
                                avatar={<Avatar src={image?.urls?.thumb} alt={image.alt} />}
                                label={image.alt?.substring(0, 15) || 'Image'}
                                onDelete={() => handleChipDelete(image)}
                                sx={{
                                    color: 'black',
                                    maxWidth: 200,
                                    '& .MuiChip-label': {
                                        overflow: 'hidden',
                                        textOverflow: 'ellipsis'
                                    }
                                }}
                            />
                        ))}
                    </Box>

                    <Stack direction="row" spacing={1}>
                        <Button onClick={onClose} color="secondary">
                            Cancel
                        </Button>
                        <Button onClick={handleFinalSubmit} variant="contained" color="primary" disabled={selected.length === 0}>
                            {singleSelect ? 'Select Image' : `Add (${selected.length}/6)`}
                        </Button>
                    </Stack>
                </Stack>
            </DialogActions>
        </Dialog>
    );
}
